import{_ as a,c as i,o as s,ag as t}from"./chunks/framework.B-aGGnuW.js";const g=JSON.parse('{"title":"Gaming","description":"","frontmatter":{},"headers":[],"relativePath":"gaming/index.md","filePath":"gaming/index.md","lastUpdated":1792149212000}'),n={name:"gaming/index.md"};function o(r,e,l,p,h,d){return s(),i("div",null,[...e[0]||(e[0]=[t(`<h1 id="gaming" tabindex="-1">Gaming <a class="header-anchor" href="#gaming" aria-label="Permalink to &quot;Gaming&quot;">​</a></h1><p>Run these commands as your regular user after installation. Start with the <a href="/installation/useful-packages#graphics-drivers">graphics driver packages</a>, including the matching 32-bit driver packages for Steam. Enable multilib in <code>/etc/pacman.conf</code> and run <code>sudo pacman -Syu</code> before installing 32-bit packages.</p><h2 id="steam-and-lutris" tabindex="-1">Steam and Lutris <a class="header-anchor" href="#steam-and-lutris" aria-label="Permalink to &quot;Steam and Lutris&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pacman</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -S</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> steam</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> lutris</span></span></code></pre></div><p>When pacman asks for a Vulkan driver provider, select the one matching your GPU. On hybrid systems, install the drivers needed by both GPUs.</p><p>Use Steam&#39;s supplied Proton first. Select a compatibility tool in a game&#39;s properties when needed. Lutris manages runners for games outside Steam; use its current runner integration rather than a separately downloaded nightly Wine package. See <a href="https://wiki.archlinux.org/title/Steam" target="_blank" rel="noreferrer">Steam</a> and <a href="https://wiki.archlinux.org/title/Lutris" target="_blank" rel="noreferrer">Lutris</a>.</p><p>If a game specifically needs GE-Proton, <a href="https://github.com/DavidoTek/ProtonUp-Qt" target="_blank" rel="noreferrer">ProtonUp-Qt</a> can install it for supported launchers. <code>protonup-qt</code> is an optional AUR package:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">paru</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -S</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> protonup-qt</span></span></code></pre></div><p>Use <code>yay</code> instead if that is your installed helper. The old Wine-GE project is archived; its <a href="https://github.com/GloriousEggroll/wine-ge-custom" target="_blank" rel="noreferrer">upstream README</a> points to the umu-based approach for running GE-Proton outside Steam. Follow your launcher&#39;s current integration.</p><h2 id="standalone-wine" tabindex="-1">Standalone Wine <a class="header-anchor" href="#standalone-wine" aria-label="Permalink to &quot;Standalone Wine&quot;">​</a></h2><p>For Windows applications outside a managed launcher:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pacman</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -S</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> wine</span></span></code></pre></div><p><code>wine-staging</code> is an alternative when an application needs staging patches. Current Arch Wine packages use the new WoW64 mode, so do not copy old lists of dozens of <code>lib32-*</code> Wine dependencies. Steam&#39;s 32-bit graphics requirements still apply separately.</p><p>Existing 32-bit-only Wine prefixes may need recreation for the <a href="https://archlinux.org/news/transition-to-the-new-wow64-wine-and-wine-staging/" target="_blank" rel="noreferrer">WoW64 transition</a>. Back up saves and application data before replacing a prefix; do not delete it blindly.</p><p>Modern Wine supports NTSync, and Arch packages supply its module-loading integration. Different Proton or Wine runners can use different synchronization implementations. Keep system-wide file-descriptor limits at their defaults unless a specific runner documents a need to change them. See <a href="https://wiki.archlinux.org/title/Wine#Synchronization_primitives" target="_blank" rel="noreferrer">Wine synchronization primitives</a>.</p><h2 id="optional-performance-tools" tabindex="-1">Optional performance tools <a class="header-anchor" href="#optional-performance-tools" aria-label="Permalink to &quot;Optional performance tools&quot;">​</a></h2><p>GameMode can temporarily change selected system settings while a game runs:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pacman</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -S</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> gamemode</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> lib32-gamemode</span></span></code></pre></div><p>For Steam games, set the launch option to <code>gamemoderun %command%</code> if you want to use it. See <a href="https://wiki.archlinux.org/title/GameMode" target="_blank" rel="noreferrer">GameMode</a> for configuration and testing.</p><p>For supported GPU monitoring and controls, <a href="https://github.com/ilya-zlobintsev/LACT" target="_blank" rel="noreferrer">LACT</a> is available in the official repositories:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pacman</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -S</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> lact</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> enable</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --now</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> lactd.service</span></span></code></pre></div><p>Check hardware support before changing power, voltage or clock settings. NVIDIA users can also install <code>nvidia-settings</code>, although some controls are unavailable in Wayland sessions.</p><h2 id="optional-kernels" tabindex="-1">Optional kernels <a class="header-anchor" href="#optional-kernels" aria-label="Permalink to &quot;Optional kernels&quot;">​</a></h2><p>The standard Arch kernel is a suitable starting point. If you want to compare <code>linux-zen</code>, keep <code>linux</code> installed as a recovery option:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pacman</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -S</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> linux-zen</span></span></code></pre></div><p>External modules need matching headers, such as <code>linux-zen-headers</code>. For Turing-or-newer NVIDIA hardware using the current driver, switch to <code>nvidia-open-dkms</code> and install headers for <strong>every</strong> installed kernel. Let pacman handle the conflicting prebuilt module package in the normal transaction. Legacy GPUs require their matching legacy DKMS branch; do not force-remove dependencies.</p><p>Regenerate initramfs images and check for module build errors:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mkinitcpio</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -P</span></span></code></pre></div><p>With GRUB:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> grub-mkconfig</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -o</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /boot/grub/grub.cfg</span></span></code></pre></div><p>With systemd-boot, copy your working <code>/boot/loader/entries/arch.conf</code> to <code>arch-zen.conf</code>, retain its root/encryption options, and change the title, <code>linux</code> and <code>initrd</code> lines to:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>title Arch Linux Zen</span></span>
<span class="line"><span>linux /vmlinuz-linux-zen</span></span>
<span class="line"><span>initrd /initramfs-linux-zen.img</span></span></code></pre></div><p>Check <code>bootctl list</code> and the files in <code>/boot</code> before rebooting. Keep the original entry available.</p><p>More hardware-specific guidance is in <a href="https://wiki.archlinux.org/title/Gaming" target="_blank" rel="noreferrer">Gaming</a>.</p>`,34)])])}const k=a(n,[["render",o]]);export{g as __pageData,k as default};
